import pandas as pd, numpy as np, re
from statsmodels.tsa.filters.hp_filter import hpfilter

def extract_series(path):
    df=pd.read_excel(path, header=None)
    annual={}
    qvals={}
    for _, row in df.iterrows():
        label=row.iloc[0]
        if pd.isna(label):
            continue
        s=str(label).strip()
        if s.startswith('Source') or s.startswith('1 ') or s.startswith('2 ') or s.startswith('[Billions') or s.startswith('TABLE'):
            continue
        m=re.match(r'^(\d{4})\.??(?::\s*([IVX]+)\.)?$', s)
        if not m:
            # quarter rows like '    II.'
            m=re.match(r'^[IVX]+\.$', s)
            if m:
                continue
            else:
                # maybe '2024: I.' with spaces
                m=re.match(r'^(\d{4}):\s*([IVX]+)\.$', s)
        if m:
            year=int(m.group(1))
            q=m.group(2)
            val=row.iloc[1]
            if pd.isna(val):
                continue
            if q is None:
                annual[year]=float(val)
            else:
                qvals.setdefault(year,[]).append(float(val))
    for y,vals in qvals.items():
        annual[y]=np.mean(vals)
    ser=pd.Series(annual).sort_index()
    return ser.loc[1973:2024]

pce=extract_series('/root/ERP-2025-table10.xls')
pfi=extract_series('/root/ERP-2025-table12.xls')
cpi=pd.read_excel('/root/CPI.xlsx').set_index('Year')['CPI_2024'].loc[1973:2024]
print(len(pce),len(pfi),len(cpi))
print(pce.head(), pce.tail())
print(pfi.head(), pfi.tail())
real_pce=pce/cpi
real_pfi=pfi/cpi
cycle_pce,_=hpfilter(np.log(real_pce),lamb=100)
cycle_pfi,_=hpfilter(np.log(real_pfi),lamb=100)
cor=np.corrcoef(cycle_pce,cycle_pfi)[0,1]
print('corr',cor)
